import { FormEvent, useEffect, useState } from "react";

import { api } from "../api/client";
import { AsyncState } from "../components/common/AsyncState";

type AgentOptions = {
  models: Array<{ id: string; name: string; context: string; status: string }>;
  knowledgeBases: Array<{ id: string; name: string; docs: number }>;
};

const STEPS = ["基本信息", "模型选择", "知识库绑定", "调试预览", "提交审核"];

export default function AgentCreatePage() {
  const [step, setStep] = useState(0);
  const [options, setOptions] = useState<AgentOptions | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  const [form, setForm] = useState({
    name: "LF13 区块排期助手",
    description: "面向 LF13 区块计划人员的个性化排期辅助智能体。",
    model: "DeepSeek V3",
    knowledgeBase: "钻完修井知识库",
  });

  useEffect(() => {
    api<AgentOptions>("/my-agents/options").then(setOptions).catch((err) => setError(err.message));
  }, []);

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (step < STEPS.length - 1) {
      setStep(step + 1);
      return;
    }
    await api("/my-agents", { method: "POST", body: form });
    setDone(true);
  }

  if (done) {
    return (
      <section className="page-stack">
        <div className="panel success-panel">
          <h2>智能体创建成功</h2>
          <p>「{form.name}」已进入调试中状态，可继续配置工作流或提交发布审核。</p>
          <div className="action-row">
            <a className="primary-action" href="/my-agents">查看我的智能体</a>
            <a className="secondary-action" href="/platform">进入开发平台</a>
          </div>
        </div>
      </section>
    );
  }

  return (
    <AsyncState loading={!options && !error} error={error}>
      {options && (
        <section className="page-stack">
          <div className="page-heading">
            <span className="eyebrow">Agent Builder</span>
            <h2>创建智能体</h2>
            <p>按步骤完成模型选择、知识库绑定和调试预览。</p>
          </div>

          <div className="step-bar">
            {STEPS.map((label, index) => (
              <span className={index <= step ? "active" : ""} key={label}>{index + 1}. {label}</span>
            ))}
          </div>

          <form className="panel wizard-form" onSubmit={submit}>
            {step === 0 && (
              <>
                <label>智能体名称<input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>
                <label>描述<textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} /></label>
              </>
            )}
            {step === 1 && (
              <div className="option-grid">
                {options.models.map((model) => (
                  <button
                    className={`option-card ${form.model === model.name ? "active" : ""}`}
                    key={model.id}
                    onClick={() => setForm({ ...form, model: model.name })}
                    type="button"
                  >
                    <strong>{model.name}</strong>
                    <span>{model.context} · {model.status}</span>
                  </button>
                ))}
              </div>
            )}
            {step === 2 && (
              <div className="option-grid">
                {options.knowledgeBases.map((kb) => (
                  <button
                    className={`option-card ${form.knowledgeBase === kb.name ? "active" : ""}`}
                    key={kb.id}
                    onClick={() => setForm({ ...form, knowledgeBase: kb.name })}
                    type="button"
                  >
                    <strong>{kb.name}</strong>
                    <span>{kb.docs} 文档</span>
                  </button>
                ))}
              </div>
            )}
            {step === 3 && (
              <div className="preview-box">
                <h4>调试预览</h4>
                <p><strong>用户：</strong>帮我检查 LF13 区块 6 月排期冲突</p>
                <p><strong>智能体：</strong>已绑定「{form.knowledgeBase}」，将基于 {form.model} 检索排期规则并输出冲突清单。</p>
                <blockquote>引用：钻完修井排期规则库 · 资源独占约束</blockquote>
              </div>
            )}
            {step === 4 && (
              <div className="preview-box">
                <h4>确认提交</h4>
                <div className="mini-row"><strong>名称</strong><span>{form.name}</span></div>
                <div className="mini-row"><strong>模型</strong><span>{form.model}</span></div>
                <div className="mini-row"><strong>知识库</strong><span>{form.knowledgeBase}</span></div>
                <p>提交后将进入「调试中」状态，可在我的智能体页面发起发布审核。</p>
              </div>
            )}
            <div className="action-row">
              {step > 0 && <button className="secondary-action" onClick={() => setStep(step - 1)} type="button">上一步</button>}
              <button className="primary-action" type="submit">
                {step === STEPS.length - 1 ? "创建智能体" : "下一步"}
              </button>
            </div>
          </form>
        </section>
      )}
    </AsyncState>
  );
}

