function useCurrentPath() {
  const [path, setPath] = useState(window.location.pathname);

  useEffect(() => {
    const onPopState = () => setPath(window.location.pathname);
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  return path;
}

export default function App() {
  const path = useCurrentPath();
  const normalizedPath = path === "" ? "/" : path;

  if (normalizedPath === "/login") {
    return <LoginPage />;
  }

  let page = <DashboardPage />;
  if (normalizedPath === "/agents") page = <AgentsPage />;
  if (normalizedPath.startsWith("/chat/")) page = <ChatPage agentId={normalizedPath.split("/").pop() ?? "schedule"} />;
  if (normalizedPath === "/schedule") page = <SchedulePage />;
  if (normalizedPath === "/reports") page = <ReportsPage />;
  if (normalizedPath === "/maintenance") page = <MaintenancePage />;
  if (normalizedPath === "/field-data") page = <FieldDataPage />;
  if (normalizedPath === "/production") page = <ProductionPage />;
  if (normalizedPath === "/lab") page = <LabPage />;
  if (normalizedPath === "/platform") page = <PlatformPage />;
  if (normalizedPath === "/admin") page = <AdminPage />;
  if (normalizedPath === "/feedback") page = <FeedbackPage />;
  if (normalizedPath === "/expert") page = <ExpertPage />;
  if (normalizedPath === "/governance") page = <GovernancePage />;
  if (normalizedPath === "/history") page = <HistoryPage />;
  if (normalizedPath === "/personal") page = <PersonalSpacePage />;
  if (normalizedPath === "/my-agents") page = <MyAgentsPage />;
  if (normalizedPath === "/my-agents/create") page = <AgentCreatePage />;

  return <AppLayout currentPath={normalizedPath}>{page}</AppLayout>;
}

import { FormEvent, useEffect, useState } from "react";

import { api } from "../api/client";
import { AsyncState } from "../components/common/AsyncState";
import type { Agent, ChatResponse } from "../data/types";

type ChatPageProps = {
  agentId: string;
};

export default function ChatPage({ agentId }: ChatPageProps) {
  const [agent, setAgent] = useState<Agent | null>(null);
  const [message, setMessage] = useState("");
  const [response, setResponse] = useState<ChatResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  useEffect(() => {
    api<Agent>(`/agents/${agentId}`).then(setAgent).catch((err) => setError(err.message));
  }, [agentId]);

  async function submit(event: FormEvent) {
    event.preventDefault();
    const finalMessage = message || agent?.recommended_questions[0] || "请给出业务建议";
    setMessage(finalMessage);
    setLoading(true);
    setResponse(null);
    setNotice(null);
    try {
      const result = await api<ChatResponse>("/chat", {
        method: "POST",
        body: { agentId, message: finalMessage },
      });
      setResponse(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : "请求失败");
    } finally {
      setLoading(false);
    }
  }

  async function saveNote() {
    if (!response || !agent) return;
    await api("/notes", {
      method: "POST",
      body: {
        title: `${agent.name} - ${message.slice(0, 20) || "对话笔记"}`,
        content: response.answer,
        source: agent.name,
      },
    });
    setNotice("笔记已保存，可在个人空间查看。");
  }

  function exportReport() {
    if (!response) return;
    const text = [
      `# ${agent?.name ?? "AI 输出"}`,
      "",
      response.answer,
      "",
      "## 引用来源",
      ...response.citations.map((c) => `- ${c.title} (${c.source}): ${c.excerpt}`),
    ].join("\n");
    const blob = new Blob([text], { type: "text/markdown" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "aoqin-ai-report.md";
    link.click();
    URL.revokeObjectURL(url);
    setNotice("报告已导出为 Markdown 文件。");
  }

  function handleAction(action: string) {
    if (!response) return;
    if (action.includes("笔记")) {
      saveNote();
      return;
    }
    if (action.includes("反馈")) {
      window.location.href = "/feedback";
      return;
    }
    if (action.includes("工作台") && response.workbenchRoute) {
      window.location.href = response.workbenchRoute;
    }
  }

  return (
    <AsyncState loading={!agent && !error} error={error}>
      {agent && (
        <section className="page-stack">
          <div className="page-heading">
            <span className="eyebrow">AI Task Execution</span>
            <h2>{agent.name}</h2>
            <p>{agent.description}</p>
          </div>

          {notice && <div className="inline-notice">{notice}</div>}

          <div className="chat-layout">
            <aside className="panel">
              <h3>推荐提问</h3>
              {agent.recommended_questions.map((question) => (
                <button className="question-chip" key={question} onClick={() => setMessage(question)}>
                  {question}
                </button>
              ))}
              <h3>能力范围</h3>
              <div className="tag-row vertical">
                {agent.capabilities.map((capability) => <span key={capability}>{capability}</span>)}
              </div>
            </aside>

            <section className="panel chat-panel">
              <form className="chat-form" onSubmit={submit}>
                <textarea value={message} onChange={(event) => setMessage(event.target.value)} placeholder="输入业务问题，例如：检查当前排期是否存在资源冲突..." />
                <button className="primary-action" disabled={loading}>{loading ? "生成中..." : "发送并生成结果"}</button>
              </form>

              {response && (
                <div className="ai-result">
                  <div className="result-header">
                    <strong>AI 输出结果</strong>
                    <span>{response.confidence}% 可信度</span>
                  </div>
                  <p>{response.answer}</p>
                  <h4>引用来源</h4>
                  {response.citations.map((citation) => (
                    <blockquote key={`${citation.title}-${citation.source}`}>
                      <strong>{citation.title}</strong>
                      <span>{citation.source}</span>
                      <p>{citation.excerpt}</p>
                    </blockquote>
                  ))}
                  <div className="action-row">
                    {response.nextActions.map((action) => (
                      <button key={action} onClick={() => handleAction(action)} type="button">{action}</button>
                    ))}
                    <button onClick={exportReport} type="button">导出报告</button>
                    <a className="secondary-action" href="/feedback">提交反馈</a>
                  </div>
                </div>
              )}
            </section>
          </div>
        </section>
      )}
    </AsyncState>
  );
}

import { FormEvent, useEffect, useState } from "react";

import { api } from "../api/client";
import { AsyncState } from "../components/common/AsyncState";
import { StatusBadge } from "../components/common/StatusBadge";
import type { Feedback, FeedbackDetail } from "../data/types";

export default function FeedbackPage() {
  const [items, setItems] = useState<Feedback[]>([]);
  const [selected, setSelected] = useState<FeedbackDetail | null>(null);
  const [title, setTitle] = useState("排期方案对物料到货解释不完整");
  const [error, setError] = useState<string | null>(null);

  function load() {
    api<Feedback[]>("/feedback").then(setItems).catch((err) => setError(err.message));
  }

  useEffect(load, []);

  async function openDetail(id: string) {
    const detail = await api<FeedbackDetail>(`/feedback/${id}`);
    setSelected(detail);
  }

  async function submit(event: FormEvent) {
    event.preventDefault();
    await api<Feedback>("/feedback", {
      method: "POST",
      body: {
        source: "钻完修井智能排期",
        title,
        category: "知识缺失",
        description: "用户认为方案解释需要补充物料到货和审批影响。",
      },
    });
    load();
  }

  async function advance(item: Feedback) {
    const next = item.status === "待处理" ? "处理中" : item.status === "处理中" ? "待专家确认" : "已修复";
    await api<Feedback>(`/feedback/${item.id}`, { method: "PATCH", body: { status: next } });
    load();
    if (selected?.id === item.id) {
      openDetail(item.id);
    }
  }

  return (
    <AsyncState loading={!items.length && !error} error={error}>
      <section className="page-stack">
        <div className="page-heading">
          <span className="eyebrow">Feedback Loop</span>
          <h2>用户反馈中心</h2>
          <p>把对话、排期和报告中的问题转化为可归因、可分派、可修复的运营任务；提交后会同步生成专家工作台任务。</p>
        </div>
        <form className="panel feedback-form" onSubmit={submit}>
          <input value={title} onChange={(event) => setTitle(event.target.value)} />
          <button className="primary-action">提交反馈</button>
        </form>
        <div className="two-column">
          <section className="panel">
            {items.map((item) => (
              <article className={`feedback-card clickable ${selected?.id === item.id ? "active" : ""}`} key={item.id}>
                <div onClick={() => openDetail(item.id)} role="button" tabIndex={0}>
                  <span>{item.source} · {item.category}</span>
                  <h3>{item.title}</h3>
                  <p>{item.description}</p>
                  <small>负责人：{item.owner} · {item.createdAt}</small>
                </div>
                <div>
                  <StatusBadge value={item.status} />
                  <button className="secondary-action" onClick={() => advance(item)} type="button">推进状态</button>
                </div>
              </article>
            ))}
          </section>
          <section className="panel">
            {selected?.context ? (
              <>
                <h3>反馈详情与上下文</h3>
                <div className="mini-row"><strong>智能体</strong><span>{selected.context.agentName}</span></div>
                <div className="mini-row"><strong>模型版本</strong><span>{selected.context.modelVersion}</span></div>
                <div className="mini-row"><strong>用户输入</strong><span>{selected.context.userInput}</span></div>
                <div className="mini-row"><strong>AI 输出</strong><span>{selected.context.aiOutput}</span></div>
                <h4>归因标签</h4>
                <div className="tag-row">
                  {selected.context.attribution.map((tag) => <span key={tag}>{tag}</span>)}
                </div>
                <a className="secondary-action" href="/expert">查看专家任务池</a>
              </>
            ) : (
              <p>点击左侧反馈卡片查看上下文追踪详情。</p>
            )}
          </section>
        </div>
      </section>
    </AsyncState>
  );
}

